    unma=set(id(o) for o in cb)
    for oa in ca:
        best=None
        for ob in sorted(cb,key=lambda o:-o['size']):
            if ob['color']!=oa['color']: continue
            if id(ob) not in unma: continue
            shift=(ob['r0']-oa['r0'],ob['c0']-oa['c0'])
            # does shifted OA shape fit inside OB? use overlap
            ov=sum(1 for a,b in oa['norm'] if (a+shift[0],b+shift[1]) in set(ob['norm']))
            if best is None or ov>=best[0] and ov>1: best=(ov,shift,id(ob))
        if best and best[0]>1:
            ov_,shift_,id_ = best
            out.append((oa,shift_))
            unma.discard(id_)
        else:
            out.append((oa,None))
    return out
