    return G
G=load()
def comps(g,bgv):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for r in range(H):
        for c in range(W):
            if not seen[r][c] and g[r][c]!=bgv:
                st=[(r,c)]; seen[r][c]=True; col=g[r][c]
                while st:
                    y,x=st.pop()
                    for dy,dx in ((1,0),(0,1),(-1,0),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]!=bgv:
                            seen[ny][nx]=True; st.append((ny,nx))
                out.append(dict(cells=set(st),color=col,sz=len(st)))
