def variants(cells):
    cur=list(cells)
    out=set()
    out.add(norm(cur))
    # rotations
    prev=cur
    for _ in range(4):
        nxt=[(x,-y) for y,x in prev]; prev=nxt
        out.add(norm(set(nxt)))
    # reflections of each rotation
    fls=[(lambda y,x: (y,x)),(lambda y,x: (y,-x)),(lambda y,x: (-y,x)),(lambda y,x: (-y,-x))]
    ps=cur
    for _ in range(4):
        f2=set()
        for fl in fls:
            f2.add(norm([fl(y,x) for y,x in prev]))
        out.update(f2)
        prev=[(x,-y) for y,x in prev]
    return out
